// Cosmetic fields and geometry mirror DeityPassCustomizationRenderer. Gameplay
// ticket colors and symbol IDs are never changed by this module.
export const DEITY_COLOR_FIELDS = Object.freeze([
  'rimColor', 'badgeBackgroundColor', 'symbolColor', 'backgroundColor', 'outlineColor',
]);
export const DEITY_GEOMETRY_BOUNDS = Object.freeze({
  unitsPerSvgUnit: 100, minRadius: 1200, maxRadius: 4890,
  defaultRadius: 4600, innerHalfExtent: 4890, innerCornerRadius: 1090,
});
export const DEITY_ART_UPDATED_EVENT = 'deity:art-updated';

export function validateDeitySymbol(symbolId) {
  if (!Number.isInteger(symbolId) || symbolId < 0 || symbolId > 31) throw new Error('Choose a Deity symbol.');
  return symbolId;
}

export function normalizeDeityColors(colors, symbolId) {
  validateDeitySymbol(symbolId);
  return Object.fromEntries(DEITY_COLOR_FIELDS.map(key => {
    const value = String(colors?.[key] ?? '').trim().toLowerCase();
    if (value !== '' && !/^#[0-9a-f]{6}$/.test(value)) throw new Error('Use a six-digit hex color, like #ab8d3f.');
    if (key === 'symbolColor' && symbolId < 8 && value) throw new Error('Crypto logos keep their original colors.');
    return [key, value];
  }));
}

export function deityColorsEqual(a, b) {
  return DEITY_COLOR_FIELDS.every(key => String(a?.[key] || '').toLowerCase() === String(b?.[key] || '').toLowerCase());
}

export function deityDefaultColors(symbolId, collection) {
  const [outline, background, ink] = collection;
  const goldDice = symbolId === 29 && outline.toLowerCase() === '#ab8d3f' && ink.toLowerCase() === '#ab8d3f';
  return {
    rimColor: symbolId === 0 ? '#ed0e11' : symbolId === 6 ? '#30d100' : outline,
    badgeBackgroundColor: goldDice ? '#111111' : '#ffffff',
    symbolColor: symbolId < 8 ? '' : ink,
    backgroundColor: background, outlineColor: outline,
  };
}

export function effectiveDeityColors(overrides, defaults) {
  return Object.fromEntries(DEITY_COLOR_FIELDS.map(key => [key, overrides[key] || defaults[key]]));
}

export function deityPositionLimit(radius, bounds = DEITY_GEOMETRY_BOUNDS) {
  if (!Number.isInteger(radius) || radius < bounds.minRadius || radius > bounds.maxRadius) throw new Error('Badge size is outside the allowed range.');
  return bounds.innerHalfExtent - radius;
}

export function validateDeityGeometry(geometry, bounds = DEITY_GEOMETRY_BOUNDS) {
  const { radius, centerX, centerY } = geometry;
  const limit = deityPositionLimit(radius, bounds);
  if (![centerX, centerY].every(n => Number.isInteger(n) && Math.abs(n) <= limit)) {
    throw new Error('Keep the whole badge inside the card.');
  }
  return { radius, centerX, centerY };
}

export function clampDeityGeometry(geometry, bounds = DEITY_GEOMETRY_BOUNDS) {
  const radius = Math.max(bounds.minRadius, Math.min(bounds.maxRadius, Math.round(geometry.radius)));
  const limit = deityPositionLimit(radius, bounds);
  const clamp = n => Math.max(-limit, Math.min(limit, Math.round(n))) + 0;
  return { radius, centerX: clamp(geometry.centerX), centerY: clamp(geometry.centerY) };
}

export function deityGeometryEqual(a, b) {
  return ['radius', 'centerX', 'centerY'].every(key => a?.[key] === b?.[key]);
}

export function decodeDeityDataUri(uri, mime) {
  if (typeof uri !== 'string' || uri.length > 2_000_000) throw new Error('Could not read the NFT artwork.');
  const prefix = `data:${mime}`;
  if (!uri.startsWith(prefix)) throw new Error('Could not read the NFT artwork.');
  const comma = uri.indexOf(','), encoding = uri.slice(prefix.length, comma);
  if (encoding === ';base64') return new TextDecoder().decode(Uint8Array.from(atob(uri.slice(comma + 1)), c => c.charCodeAt(0)));
  if (encoding === '') return decodeURIComponent(uri.slice(comma + 1));
  throw new Error('Could not read the NFT artwork.');
}

/** Keep SVG in an isolated image. Preserve the on-chain icon and middle ring. */
export function previewDeityArt(appearance, colors, geometry, symbolId, bounds = DEITY_GEOMETRY_BOUNDS) {
  validateDeityGeometry(geometry, bounds);
  const palette = normalizeDeityColors(colors, symbolId);
  if (DEITY_COLOR_FIELDS.some(key => key !== 'symbolColor' && !palette[key]) || (symbolId >= 8 && !palette.symbolColor)) throw new Error('Could not load the default colors.');
  const svg = decodeDeityDataUri(appearance?.src, 'image/svg+xml');
  const doc = new DOMParser().parseFromString(svg, 'image/svg+xml');
  const root = doc.documentElement;
  const frame = [...root.children].find(node => node.localName === 'rect');
  const badge = doc.getElementById('badge');
  const rings = [...(badge?.children || [])].filter(node => node.localName === 'circle');
  const ink = [...(badge?.children || [])].find(node => node.localName === 'g')?.firstElementChild;
  if (root.localName !== 'svg' || !frame || rings.length !== 3 || !ink || rings[0].getAttribute('r') !== '46') throw new Error('This NFT artwork cannot be customized here.');
  frame.setAttribute('stroke', palette.outlineColor);
  frame.setAttribute('fill', palette.backgroundColor);
  rings[0].setAttribute('fill', palette.rimColor);
  rings[2].setAttribute('fill', palette.badgeBackgroundColor);
  if (symbolId >= 8) {
    ink.setAttribute('fill', palette.symbolColor);
    ink.setAttribute('stroke', palette.symbolColor);
  }
  const scale = Math.floor(geometry.radius * 1_000_000 / bounds.defaultRadius) / 1_000_000;
  badge.setAttribute('transform', `matrix(${scale} 0 0 ${scale} ${geometry.centerX / bounds.unitsPerSvgUnit} ${geometry.centerY / bounds.unitsPerSvgUnit})`);
  return { src: `data:image/svg+xml,${encodeURIComponent(new XMLSerializer().serializeToString(root))}` };
}
